class Solution { public: int minCharacters(string a,string b){array<int,26> first{},second{};for(char letter:a)++first[letter-'a'];for(char letter:b)++second[letter-'a'];int answer=a.size()+b.size();for(int letter=0;letter<26;++letter)answer=min(answer,(int)a.size()+(int)b.size()-first[letter]-second[letter]);int prefixFirst=0,prefixSecond=0;for(int boundary=0;boundary<25;++boundary){prefixFirst+=first[boundary];prefixSecond+=second[boundary];answer=min(answer,(int)a.size()-prefixFirst+prefixSecond);answer=min(answer,(int)b.size()-prefixSecond+prefixFirst);}return answer;} };
